/**
 * attribution.ts — AI attribution must never appear in this project.
 *
 * Nothing in this repository, its commits, issues, pull requests or comments
 * may be authored as, or credit, Claude Code, Claude or any other AI tool or
 * agent harness (no "Generated by/with …" footers, no Co-Authored-By trailers,
 * no session links). See AGENTS.md rule 6.
 *
 * These helpers detect and strip such lines so they are removed wherever text
 * enters the repo (comments, synced GitHub issues) and are caught by the guard
 * (`scripts/check-attribution.ts`, `tests/attribution-guard.test.ts`).
 */

const AI_NAMES = "claude|anthropic|chatgpt|openai|gpt-?\\d*|copilot|gemini|codex|cursor|aider|devin|windsurf|hermes";

/** One line of AI attribution. */
export const AI_ATTRIBUTION_LINE_PATTERNS: readonly RegExp[] = [
  // "Generated by Claude Code", "🤖 Generated with [Claude Code](…)", "_Generated by ChatGPT_"
  new RegExp(`(?:^|[^A-Za-z0-9])generated\\s+(?:by|with|using)\\s+\\[?\\s*(?:${AI_NAMES})(?![A-Za-z0-9])`, "i"),
  // Co-Authored-By trailers crediting an AI
  new RegExp(`^\\s*co-authored-by:.*(?:${AI_NAMES}|noreply@anthropic\\.com)`, "i"),
  // Session trailers
  /^\s*claude-session\s*:/i,
  // Session / product links
  /claude\.(?:ai|com)\/(?:code|claude-code)/i,
];

export function lineHasAiAttribution(line: string): boolean {
  return AI_ATTRIBUTION_LINE_PATTERNS.some((re) => re.test(line));
}

export function containsAiAttribution(text: string): boolean {
  return text.split(/\r?\n/).some(lineHasAiAttribution);
}

/**
 * Remove AI attribution lines. A horizontal rule (`---`) that only separated
 * the footer from the content is removed with it; other rules are kept.
 * Trailing blank lines are trimmed when anything was removed.
 */
export function stripAiAttribution(text: string): string {
  if (!containsAiAttribution(text)) return text;
  const lines = text.split(/\r?\n/);
  const out: string[] = [];
  for (const line of lines) {
    if (lineHasAiAttribution(line)) continue;
    out.push(line);
  }
  // Drop a dangling separator left at the end by the removed footer.
  while (out.length > 0 && out[out.length - 1].trim() === "") out.pop();
  if (out.length > 0 && /^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/.test(out[out.length - 1])) out.pop();
  while (out.length > 0 && out[out.length - 1].trim() === "") out.pop();
  return out.join("\n");
}
